--
-- Name: wikijs_pages_vector_align_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wikijs_pages_vector_align_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  page_id integer;
BEGIN
  SELECT p.id INTO page_id
    FROM public.pages p
   WHERE p.path = NEW.path AND p."localeCode" = NEW.locale
   ORDER BY p.id DESC
   LIMIT 1;
  IF page_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public."pagesVector" v WHERE v.id = page_id) THEN
    NEW.id := page_id;
  ELSIF EXISTS (SELECT 1 FROM public."pagesVector" v WHERE v.id = NEW.id) THEN
    NEW.id := (SELECT COALESCE(MAX(v.id), 0) + 1 FROM public."pagesVector" v);
  END IF;
  RETURN NEW;
END
$$;


