INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (1, 'Some of these non-payment holds may not be current. Worth checking against the June remittance advices before the report goes out.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 30, 12, '', 'Sam Petrakis', 'sam.petrakis@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (2, 'Please confirm the open balances shown here are current as of the June remittance cycle.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 31, 12, '', 'Sam Petrakis', 'sam.petrakis@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (3, 'This letter triggered the backlog review directive. Response due 08/15/2025, APUC briefing 09/10/2025.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 17, 4, '', 'Harriet Ngoyi', 'harriet.ngoyi@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (4, 'Our two school arrays have been construction-complete since April and May. The school year is approaching and we need these systems energized as soon as possible.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 24, 16, '', 'Rosa Camarena', 'rosa.camarena@brookfenusd.org', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (5, 'No site gets PTO before its telemetry link is live and commissioned. All seven are waiting on equipment.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 24, 11, '', 'Lena Kovalchuk', 'lena.kovalchuk@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (6, 'These twelve have been parked for some time. Please confirm the hold is appropriate and what routing each one needs.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 39, 9, '', 'Evan Solberg', 'evan.solberg@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (7, 'Flagged at intake for abnormality review. Please work this against the standard before the hold is cleared.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 6, 8, '', 'Tomás Ibarra', 'tomas.ibarra@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (8, 'This screening memo needs review before the determination is final. Please check it against the current procedure.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 52, 5, '', 'Meera Vellanki', 'meera.vellanki@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (9, 'The ISA was executed on 07/03/2025. Please advise whether the requested change can be handled as an amendment.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 15, 5, '', 'Meera Vellanki', 'meera.vellanki@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (10, 'This map export is from May 2024 and the quarterly refresh is overdue.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 28, 7, '', 'June Halloway', 'june.halloway@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (11, 'Filed as standalone. Please confirm the program classification before screening proceeds.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 7, 5, '', 'Meera Vellanki', 'meera.vellanki@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (12, 'Please verify the inverter on this checklist against the current Certified Equipment List before the waiver is granted.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 11, 9, '', 'Evan Solberg', 'evan.solberg@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (13, 'Waiver eligibility here needs checking against the current CEL edition.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 10, 9, '', 'Evan Solberg', 'evan.solberg@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (14, 'Backhaul update for the Elmsworth Northside site: the fibre run is scheduled with the carrier for Q1 2026. The telemetry link cannot be commissioned before then, whatever equipment arrives.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 24, 11, '', 'Lena Kovalchuk', 'lena.kovalchuk@alleniom.com', '', 0);
INSERT INTO public.comments (id, content, "createdAt", "updatedAt", "pageId", "authorId", render, name, email, ip, "replyTo") VALUES (15, 'Note for the file: the inverter installed at Lockmere Middle is a Selvix SV-720. It was substituted on site after this checklist was submitted and the checklist still shows the original unit.', '2026-11-19T12:07:39.022930+00:00', '2026-11-19T12:07:39.022930+00:00', 12, 9, '', 'Evan Solberg', 'evan.solberg@alleniom.com', '', 0);


