INSERT INTO public.pages (id, path, hash, title, description, "isPrivate", "isPublished", "privateNS", "publishStartDate", "publishEndDate", content, render, toc, "contentType", "createdAt", "updatedAt", "editorKey", "localeCode", "authorId", "creatorId", extra) VALUES (71, 'der-program/equipment/pxa-2024-0099-wintbrook-der-breaker-and-relay-data', '3d2fdd5ed2ec834b74da', 'PXA-2024-0099 Wintbrook DER Breaker and Relay Data', 'Equipment data for the Wintbrook DER interconnection breaker and relay', false, true, '', '', '', '# PXA-2024-0099 Wintbrook DER Breaker and Relay Data

